def build(p):
    import cadquery as cq
    cx = p['R_station']
    px, pz = cx + p['pivot_r'] * math.cos(math.radians(-60)), -p['pivot_r'] * math.sin(math.radians(-60))
    ang = math.atan2(-(0 - pz), cx - px)
    ex, ez = px + p['arm_len'] * math.cos(ang), pz - p['arm_len'] * math.sin(ang)
    disk = cq.Workplane("XZ").circle(p['d'] / 2).extrude(-p['t']).translate((ex, p['t'], ez))
    stem = cq.Workplane("XZ").circle(18).extrude(-(p['y'] - 40 - p['t'])).translate((ex, p['y'] - 40, ez))
    return disk.union(stem)
